import fs from "fs";
import path from "path";
import { AgentSocketHandler } from "../agent-socket-handler";
import { DockgeServer } from "../dockge-server";
import { callbackError, callbackResult, checkLogin, DockgeSocket } from "../util-server";
import { AgentSocket } from "../../common/agent-socket";
import { log } from "../log";

/**
 * Socket handler that reads the port occupancy information from the
 * `ports.json` file in the data directory of this Dockge instance.
 *
 * The ports.json file is expected to be generated by an external shell
 * command (e.g. via `ss`) written by the host operator. When this handler
 * is invoked through the agent routing mechanism, it reads the file on the
 * host that the agent (or the current server) runs on, allowing the UI to
 * display port status for both the local host and remote Dockge agents.
 */
export class PortConfigSocketHandler extends AgentSocketHandler {
    create(socket : DockgeSocket, server : DockgeServer, agentSocket : AgentSocket) {

        // Return the parsed port status from data/ports.json of this host.
        // The file is expected to be a map of hostname -> { port: inUse } :
        //   { "amd": { "4000": true, "4001": false }, "piper": { "4000": false } }
        agentSocket.on("getPortConfig", async (callback) => {
            try {
                checkLogin(socket);

                const filePath = path.join(server.config.dataDir, "ports.json");

                // A map of hostname -> { port -> inUse }
                let hosts : Record<string, Record<string, boolean>> = {};

                if (fs.existsSync(filePath)) {
                    const raw = fs.readFileSync(filePath, "utf-8");
                    try {
                        const parsed = JSON.parse(raw);
                        if (parsed && typeof parsed === "object") {
                            hosts = parsed;
                        }
                    } catch (e) {
                        log.error("getPortConfig", "Invalid JSON in " + filePath + ": " + (e as Error).message);
                        throw new Error("Invalid JSON in " + filePath);
                    }
                } else {
                    log.debug("getPortConfig", "File not found: " + filePath);
                }

                callbackResult({
                    ok: true,
                    hosts,
                }, callback);
            } catch (e) {
                callbackError(e, callback);
            }
        });
    }
}